package cases

import (
	"context"
	"sync"
)

type Gate struct {
	mu sync.Mutex
}

func (g *Gate) Wait(ctx context.Context) {
	g.mu.Lock()
	defer g.mu.Unlock()
	<-ctx.Done()
}

