import (
	"context"
	"fmt"
)

func Copy(ctx context.Context, values []string) ([]string, error) {
	result := make([]string, 0, len(values))
	for _, value := range values {
		select {
		case <-ctx.Done():
			return result, ctx.Err()
		default:
		}
		result = append(result, fmt.Sprintf("copy:%s", value))
	}
	return result, nil
}

