import (
	"errors"
	"sync"
)

type Ledger struct {
	mu   sync.Mutex
	seen map[string]bool
}

func (l *Ledger) Reserve(key string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.seen == nil {
		l.seen = make(map[string]bool)
	}
	if l.seen[key] {
		return false
	}
	l.seen[key] = true
	return true
}

type Gateway interface {
	Charge(string, int) error
}

type Billing struct {
	ledger  *Ledger
	gateway Gateway
}

func (b *Billing) Charge(key string, amount int) error {
	if !b.ledger.Reserve(key) {
		return errors.New("duplicate request")
	}
	return b.gateway.Charge(key, amount)
}

